const p = $('Dispatch trigger').first().json;
const riders = $input.all().map(function (i) { return i.json; });
const r = riders.find(function (x) { return String(x.Available || '').trim().toLowerCase() === 'yes' && String(x.Role || 'Rider').trim().toLowerCase() === 'rider'; });
const base = { order_id: p.order_id, customer_name: p.customer_name, customer_email: p.customer_email || '', customer_phone: p.customer_phone || '', address: p.address };
if (!r) { return [{ json: Object.assign({ found: false }, base) }]; }
return [{ json: Object.assign({ found: true, Staff_ID: r.Staff_ID, rider_name: r.Name, vehicle: r.Vehicle, rider_phone: r.Phone }, base) }];

const pick = $('Pick first free rider').first().json;
let max = 1000;
$input.all().forEach(function (i) {
  const m = String(i.json.Dispatch_ID || '').match(/^DSP-(\d+)$/);
  if (m && Number(m[1]) > max) { max = Number(m[1]); }
});
return [{ json: { Dispatch_ID: 'DSP-' + (max + 1), Order_ID: pick.order_id, Rider: pick.rider_name, Vehicle: pick.vehicle, Dispatched_At: $now.toFormat('yyyy-MM-dd HH:mm:ss'), Delivered_At: '', Status: 'Dispatched' } }];

const form = $('Mark delivered form').first().json;
const wanted = String(form.Order_ID || '').trim().toUpperCase();
const rows = function (name) { return $(name).all().map(function (i) { return i.json; }); };
const d = rows('Read dispatch for delivery').find(function (r) { return String(r.Order_ID || '').toUpperCase() === wanted && String(r.Status) === 'Dispatched'; });
if (!d) { return [{ json: { ok: false, Order_ID: wanted, message: 'No open delivery was found for ' + wanted + '. Nothing was changed.' } }]; }
const staff = rows('Read staff for delivery').find(function (r) { return String(r.Name) === String(d.Rider); });
const order = rows('Read orders for delivery').find(function (r) { return String(r.Order_ID) === String(d.Order_ID); });
const cust = order ? rows('Read customers for delivery').find(function (r) { return String(r.Customer_ID) === String(order.Customer_ID); }) : null;
return [{ json: { ok: true, Order_ID: d.Order_ID, Dispatch_ID: d.Dispatch_ID, rider_name: d.Rider, Staff_ID: staff ? staff.Staff_ID : '', customer_name: cust ? cust.Name : '', customer_email: cust ? String(cust.Email || '') : '', customer_phone: cust ? String(cust.Phone || '') : '', delivered_at: $now.toFormat('yyyy-MM-dd HH:mm:ss'), message: 'Order ' + d.Order_ID + ' marked as delivered. ' + d.Rider + ' is available again.' } }];

const orders = $('Read orders for delivery').all().map(function (i) { return i.json; }).filter(function (o) { return o.Order_ID && String(o.Status) === 'Waiting for rider'; });
orders.sort(function (a, b) { return Number(String(a.Order_ID).replace(/\D/g, '')) - Number(String(b.Order_ID).replace(/\D/g, '')); });
const o = orders[0];
if (!o) { return [{ json: { found: false } }]; }
const c = $('Read customers for delivery').all().map(function (i) { return i.json; }).find(function (x) { return String(x.Customer_ID) === String(o.Customer_ID); }) || {};
return [{ json: { found: true, order_id: o.Order_ID, customer_name: c.Name || '', customer_email: c.Email || '', customer_phone: c.Phone || '', address: c.Address || '' } }];

